import { requestIdentity } from "@/features/tenant/request";
import { getStoreConfig } from "@/features/storefront/api/config";
import { buildStoreTheme } from "@/features/storefront/theme/tokens";
import { shortName } from "@/features/pwa/schemas";

/**
 * Per-store Web App Manifest (M44 US-44.2, FR-44.02, research R-16), generated from the
 * store's `/api/v1/config/`: its name, `theme_color` from `primary_color` (through the theme
 * layer, so an invalid colour falls back like the page does), `background_color`, RTL Arabic,
 * standalone, and icons generated by `/icon`. `start_url`/`scope` are the CURRENT origin's
 * root, so a custom domain gets its own scope (M44 §8).
 */
export async function GET() {
  const identity = await requestIdentity();
  const config = await getStoreConfig(identity.store, identity.storeHost);
  const theme = buildStoreTheme(config);
  const manifest = {
    name: config.store_name,
    short_name: shortName(config.store_name),
    description: config.seo_description ?? undefined,
    start_url: "/",
    scope: "/",
    id: "/",
    display: "standalone",
    dir: "rtl",
    lang: "ar",
    background_color: theme.meta.background,
    theme_color: theme.meta.primary,
    icons: [
      { src: "/icon?size=192", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon?size=512", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon?size=512&maskable=1", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
  return new Response(JSON.stringify(manifest), {
    headers: { "content-type": "application/manifest+json; charset=utf-8", "cache-control": "no-cache" },
  });
}
